"use strict";(globalThis.webpackChunkfeldera_docs=globalThis.webpackChunkfeldera_docs||[]).push([[7838],{88449(e,n,r){r.r(n),r.d(n,{assets:()=>l,contentTitle:()=>t,default:()=>c,frontMatter:()=>d,metadata:()=>i,toc:()=>o});const i=JSON.parse('{"id":"use_cases/fine_grained_authorization/static","title":"Implementing a static FGA model","description":"In this section we will implement the file manager authorization model using Feldera.","source":"@site/docs/use_cases/fine_grained_authorization/static.md","sourceDirName":"use_cases/fine_grained_authorization","slug":"/use_cases/fine_grained_authorization/static","permalink":"/use_cases/fine_grained_authorization/static","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{},"sidebar":"docsSidebar","previous":{"title":"Use Case: Fine-Grained Authorization","permalink":"/use_cases/fine_grained_authorization/intro"},"next":{"title":"Implementing a dynamic FGA model","permalink":"/use_cases/fine_grained_authorization/dynamic"}}');var s=r(74848),a=r(28453);const d={},t="Implementing a static FGA model",l={},o=[{value:"Modeling the object graph",id:"modeling-the-object-graph",level:2},{value:"Implementing rules",id:"implementing-rules",level:2},{value:"Kicking the tires",id:"kicking-the-tires",level:2},{value:"Running at full speed",id:"running-at-full-speed",level:2}];function u(e){const n={a:"a",code:"code",em:"em",h1:"h1",h2:"h2",header:"header",li:"li",p:"p",pre:"pre",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,a.R)(),...e.components},{Details:r}=n;return r||function(e,n){throw new Error("Expected "+(n?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("Details",!0),(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.header,{children:(0,s.jsx)(n.h1,{id:"implementing-a-static-fga-model",children:"Implementing a static FGA model"})}),"\n",(0,s.jsx)(n.p,{children:"In this section we will implement the file manager authorization model using Feldera.\nWe model objects, relationships, and rules described above as SQL tables and views. We\nwill see how FGA rules naturally lend themselves to implementation as SQL queries.\nWe will also see how Feldera can evaluate these queries efficiently and\nincrementally at scale."}),"\n",(0,s.jsx)(n.p,{children:"The approach we take here works best when the authorization model is co-designed with\nthe application and doesn't change at runtime: the application can create and destroy\nusers, groups, and files, but not change the access control rules."}),"\n",(0,s.jsxs)(n.p,{children:["The implementation described in this section is available as a ",(0,s.jsx)(n.a,{href:"https://try.feldera.com/create/?name=fine-grained-auth",children:"pre-packaged example\nin the Feldera online sandbox"})," as well\nas in your local Feldera installation."]}),"\n",(0,s.jsx)(n.h2,{id:"modeling-the-object-graph",children:"Modeling the object graph"}),"\n",(0,s.jsx)(n.p,{children:"We start with modeling the three object types\u2014users, groups, and files\u2014as SQL tables:"}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-sql",children:"CREATE TABLE users (\n    id BIGINT NOT NULL PRIMARY KEY,\n    name STRING,\n    is_banned BOOL\n) WITH ('materialized' = 'true');\n\nCREATE TABLE groups (\n    id BIGINT NOT NULL PRIMARY KEY,\n    name STRING\n) WITH ('materialized' = 'true');\n\nCREATE TABLE files (\n    id BIGINT NOT NULL PRIMARY KEY,\n    name STRING,\n    -- Parent folder id; NULL for a root folder.\n    parent_id BIGINT\n) WITH ('materialized' = 'true');\n"})}),"\n",(0,s.jsxs)(n.p,{children:["Note that the ",(0,s.jsx)(n.code,{children:"parent_id"})," field models the ",(0,s.jsx)(n.code,{children:"parent"})," relationship between files."]}),"\n",(0,s.jsxs)(n.p,{children:["Next, we model ",(0,s.jsx)(n.code,{children:"member"}),", ",(0,s.jsx)(n.code,{children:"editor"}),", and ",(0,s.jsx)(n.code,{children:"viewer"})," relationships:"]}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-sql",children:"-- Member relationship models user membership in groups.\nCREATE TABLE members (\n    id BIGINT NOT NULL PRIMARY KEY,\n    user_id  BIGINT NOT NULL,\n    group_id BIGINT NOT NULL\n) WITH ('materialized' = 'true');\n\n-- Editor relationship between a group and a file that gives the group the permission\n-- to read or write the file.\nCREATE TABLE group_file_editor (\n    group_id BIGINT NOT NULL,\n    file_id BIGINT NOT NULL\n) WITH ('materialized' = 'true');\n\n-- Viewer relationship between a group and a file that gives the group the permission to read the file.\nCREATE TABLE group_file_viewer (\n    group_id BIGINT NOT NULL,\n    file_id BIGINT NOT NULL\n) WITH ('materialized' = 'true');\n"})}),"\n",(0,s.jsx)(n.h2,{id:"implementing-rules",children:"Implementing rules"}),"\n",(0,s.jsxs)(n.p,{children:["So far, we've defined objects and relationships that comprise the object graph of our application.\nWe are now ready to implement derived relationships.  We start with the ",(0,s.jsx)(n.code,{children:"group-can-write"}),"\nrelationship defined by the following two rules."]}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Rule 1:"})," ",(0,s.jsx)(n.code,{children:"editor(group, file) -> group-can-write(group, file)"}),"."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Rule 2:"})," ",(0,s.jsx)(n.code,{children:"group-can-write(group, file1) and parent(file1, file2) -> group-can-write(group, file2)"}),"."]}),"\n"]}),"\n",(0,s.jsxs)(n.p,{children:["In Rule 2 ",(0,s.jsx)(n.code,{children:"group-can-write"})," appears on both sides of the implication, indicating that this is a\nrecursive relationship. Rule 1 specifies the base case: a group has write access to all files\nfor which it is an editor. Rule 2 defines the recursive step: write permissions propagate from a\nfile to all its children.  We implement these rules as a recursive SQL view:"]}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-sql",children:"DECLARE RECURSIVE VIEW group_can_write (\n    group_id BIGINT NOT NULL,\n    file_id BIGINT NOT NULL\n);\n\nCREATE MATERIALIZED VIEW group_can_write AS\n-- Rule 1: editor(group, file) -> group-can-write(group, file).\n(\n  SELECT group_id, file_id FROM group_file_editor\n)\nUNION ALL\n-- Rule 2: group-can-write(group, file1) and parent(file1, file2) -> group-can-write(group, file2).\n(\n  SELECT\n    group_can_write.group_id,\n    files.id AS file_id\n  FROM\n    group_can_write JOIN files ON group_can_write.file_id = files.parent_id\n);\n"})}),"\n",(0,s.jsxs)(n.p,{children:["Rules for the ",(0,s.jsx)(n.code,{children:"group-can-read"})," relationship have a similar structure, with one additional\nrule (Rule 4), which states that the write permission to a file (",(0,s.jsx)(n.code,{children:"group-can-write"}),") implies\nthe read permission ",(0,s.jsx)(n.code,{children:"group-can-read"}),":"]}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Rule 3:"})," ",(0,s.jsx)(n.code,{children:"viewer(group, file) -> group-can-read(group, file)"}),"."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Rule 4:"})," ",(0,s.jsx)(n.code,{children:"group-can-write(group, file) -> group-can-read(group, file)"}),"."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Rule 5:"})," ",(0,s.jsx)(n.code,{children:"group-can-read(group, file1) and parent(file1, file2) -> group-can-read(group, file2)"}),"."]}),"\n"]}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-sql",children:"DECLARE RECURSIVE VIEW group_can_read (\n    group_id BIGINT NOT NULL,\n    file_id BIGINT NOT NULL\n);\n\nCREATE MATERIALIZED VIEW group_can_read AS\n-- Rule 3: viewer(group, file) -> group-can-read(group, file).\n(\n  SELECT group_id, file_id FROM group_file_viewer\n)\nUNION ALL\n-- Rule 4: group-can-write(group, file) -> group-can-read(group, file).\n(\n  SELECT group_id, file_id FROM group_can_write\n)\nUNION ALL\n-- Rule 5: group-can-read(group, file1) and parent(file1, file2) -> group-can-read(group, file2).\n(\n  SELECT\n    group_can_read.group_id,\n    files.id AS file_id\n FROM\n    group_can_read JOIN files ON group_can_read.file_id = files.parent_id\n);\n"})}),"\n",(0,s.jsxs)(n.p,{children:["Finally, we implement ",(0,s.jsx)(n.code,{children:"user-can-write"})," and ",(0,s.jsx)(n.code,{children:"user-can-read"})," relationships:"]}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Rule 6:"})," ",(0,s.jsx)(n.code,{children:"member(user, group) and group-can-write(group, file) and (not user.is_banned) -> user-can-write(user, file)"}),"."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Rule 7:"})," ",(0,s.jsx)(n.code,{children:"member(user, group) and group-can-read(group, file) and (not user.is_banned) -> user-can-read(user, file)"}),"."]}),"\n"]}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-sql",children:"-- Rule 6: member(user, group) and group-can-write(group, file) and (not user.is_banned) -> user-can-write(user, file).\nCREATE MATERIALIZED VIEW user_can_write AS\nSELECT DISTINCT\n    members.user_id,\n    group_can_write.file_id\nFROM\n    members\n    JOIN group_can_write ON members.group_id = group_can_write.group_id\n    JOIN users ON users.id = members.user_id\nWHERE NOT users.is_banned;\n\n-- Rule 7: member(user, group) and group-can-read(group, file) and (not user.is_banned) -> user-can-read(user, file).\nCREATE MATERIALIZED VIEW user_can_read AS\nSELECT DISTINCT\n    members.user_id,\n    group_can_read.file_id\nFROM\n    members\n    JOIN group_can_read ON members.group_id = group_can_read.group_id\n    JOIN users ON users.id = members.user_id\nWHERE NOT users.is_banned;\n"})}),"\n",(0,s.jsx)(n.p,{children:"This is it! With a few lines of SQL we implemented an incremental recursive FGA engine."}),"\n",(0,s.jsx)(n.h2,{id:"kicking-the-tires",children:"Kicking the tires"}),"\n",(0,s.jsxs)(n.p,{children:["Copy the complete SQL code below to the Feldera Web Console (or click ",(0,s.jsx)(n.code,{children:"Run"})," to open it in the Feldera\nonline sandbox)."]}),"\n",(0,s.jsxs)(r,{children:[(0,s.jsx)("summary",{children:" Expand to see full SQL code "}),(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-sql",children:"CREATE TABLE users (\n    id BIGINT NOT NULL PRIMARY KEY,\n    name STRING,\n    is_banned BOOL\n) WITH ('materialized' = 'true');\n\nCREATE TABLE groups (\n    id BIGINT NOT NULL PRIMARY KEY,\n    name STRING\n) WITH ('materialized' = 'true');\n\nCREATE TABLE files (\n    id BIGINT NOT NULL PRIMARY KEY,\n    name STRING,\n    -- Parent folder id when not NULL\n    parent_id BIGINT\n) WITH ('materialized' = 'true');\n\n-- Member relationship models user membership in groups.\nCREATE TABLE members (\n    id BIGINT NOT NULL PRIMARY KEY,\n    user_id  BIGINT NOT NULL,\n    group_id BIGINT NOT NULL\n) WITH ('materialized' = 'true');\n\n-- Editor relationship between a group and a file that gives the group the permission\n-- to read or write the file.\nCREATE TABLE group_file_editor (\n    group_id BIGINT NOT NULL,\n    file_id BIGINT NOT NULL\n) WITH ('materialized' = 'true');\n\n-- Viewer relationship between a group and a file that gives the group the permission to read the file.\nCREATE TABLE group_file_viewer (\n    group_id BIGINT NOT NULL,\n    file_id BIGINT NOT NULL\n) WITH ('materialized' = 'true');\n\nDECLARE RECURSIVE VIEW group_can_write (\n    group_id BIGINT NOT NULL,\n    file_id BIGINT NOT NULL\n);\n\nCREATE MATERIALIZED VIEW group_can_write AS\n-- Rule 1: editor(group, file) -> group-can-write(group, file).\n(\n  SELECT group_id, file_id FROM group_file_editor\n)\nUNION ALL\n-- Rule 2: group-can-write(group, file1) and parent(file1, file2) -> group-can-write(group, file2).\n(\n  SELECT\n    group_can_write.group_id,\n    files.id AS file_id\n  FROM\n    group_can_write JOIN files ON group_can_write.file_id = files.parent_id\n);\n\nDECLARE RECURSIVE VIEW group_can_read (\n    group_id BIGINT NOT NULL,\n    file_id BIGINT NOT NULL\n);\n\nCREATE MATERIALIZED VIEW group_can_read AS\n-- Rule 3: viewer(group, file) -> group-can-read(group, file).\n(\n  SELECT group_id, file_id FROM group_file_viewer\n)\nUNION ALL\n-- Rule 4: group-can-write(group, file) -> group-can-read(group, file).\n(\n  SELECT group_id, file_id FROM group_can_write\n)\nUNION ALL\n-- Rule 5: group-can-read(group, file1) and parent(file1, file2) -> group-can-read(group, file2).\n(\n  SELECT\n    group_can_read.group_id,\n    files.id AS file_id\n FROM\n    group_can_read JOIN files ON group_can_read.file_id = files.parent_id\n);\n\n-- Rule 6: member(user, group) and group-can-write(group, file) and (not user.is_banned) -> user-can-write(user, file).\nCREATE MATERIALIZED VIEW user_can_write AS\nSELECT DISTINCT\n    members.user_id,\n    group_can_write.file_id\nFROM\n    members\n    JOIN group_can_write ON members.group_id = group_can_write.group_id\n    JOIN users ON users.id = members.user_id\nWHERE NOT users.is_banned;\n\n-- Rule 7: member(user, group) and group-can-read(group, file) and (not user.is_banned) -> user-can-read(user, file).\nCREATE MATERIALIZED VIEW user_can_read AS\nSELECT DISTINCT\n    members.user_id,\n    group_can_read.file_id\nFROM\n    members\n    JOIN group_can_read ON members.group_id = group_can_read.group_id\n    JOIN users ON users.id = members.user_id\nWHERE NOT users.is_banned;\n"})})]}),"\n",(0,s.jsxs)(n.p,{children:["Start the pipeline and populate the object graph to match the ",(0,s.jsx)(n.a,{href:"/use_cases/fine_grained_authorization/intro#object-graph",children:"example"})," by issuing the following\nad hoc queries:"]}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-sql",children:"INSERT INTO users VALUES\n    (1, 'emily', FALSE),\n    (2, 'irene', FALSE),\n    (3, 'adam', TRUE);\n\nINSERT INTO groups VALUES\n    (1, 'engineering'),\n    (2, 'it'),\n    (3, 'accounting');\n\nINSERT INTO files VALUES\n    (1, 'designs', NULL),\n    (2, 'financials', NULL),\n    (3, 'f1', 1),\n    (4, 'f2', 1),\n    (5, 'f3', 2);\n\nINSERT INTO members VALUES\n    (1, 1, 1), -- emily is in engineering\n    (2, 2, 2), -- irene is in IT\n    (3, 3, 3); -- adam is in accounting\n\nINSERT INTO group_file_editor VALUES\n    (1, 1),         -- 'engineering' can edit 'designs'\n    (2, 1), (2, 2), -- 'it' can edit 'designs' and 'financials'\n    (3, 2);         -- 'accounting' can edit 'financials'.\n\nINSERT INTO group_file_viewer VALUES\n    (3, 1); -- 'accounting' can view 'designs'.\n"})}),"\n",(0,s.jsx)(n.p,{children:"We can now validate the output of the program, e.g.:"}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-sql",children:"SELECT\n  users.name AS user_name,\n  files.name AS file_name\nFROM\n  user_can_read\n  JOIN users ON users.id = user_can_read.user_id\n  JOIN files ON files.id = user_can_read.file_id;\n"})}),"\n",(0,s.jsxs)(n.table,{children:[(0,s.jsx)(n.thead,{children:(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.th,{children:"user_name"}),(0,s.jsx)(n.th,{children:"file_name"})]})}),(0,s.jsxs)(n.tbody,{children:[(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"emily"}),(0,s.jsx)(n.td,{children:"designs"})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"irene"}),(0,s.jsx)(n.td,{children:"designs"})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"irene"}),(0,s.jsx)(n.td,{children:"financials"})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"irene"}),(0,s.jsx)(n.td,{children:"f3"})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"emily"}),(0,s.jsx)(n.td,{children:"f1"})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"irene"}),(0,s.jsx)(n.td,{children:"f1"})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"emily"}),(0,s.jsx)(n.td,{children:"f2"})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"irene"}),(0,s.jsx)(n.td,{children:"f2"})]})]})]}),"\n",(0,s.jsxs)(n.p,{children:["As expected, ",(0,s.jsx)(n.code,{children:"emily"}),", being a member of ",(0,s.jsx)(n.code,{children:"engineering"}),", has read access to all files under the ",(0,s.jsx)(n.code,{children:"designs"})," folder,\nwhile ",(0,s.jsx)(n.code,{children:"irene"}),", a member of ",(0,s.jsx)(n.code,{children:"it"}),", can read files under both ",(0,s.jsx)(n.code,{children:"designs"})," and ",(0,s.jsx)(n.code,{children:"financials"}),"."]}),"\n",(0,s.jsxs)(n.p,{children:["Next we make an incremental change to the object graph, adding ",(0,s.jsx)(n.code,{children:"emily"})," to the ",(0,s.jsx)(n.code,{children:"it"})," group:"]}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-sql",children:"INSERT INTO members VALUES (4, 1, 2);\n"})}),"\n",(0,s.jsxs)(n.p,{children:["Running the ",(0,s.jsx)(n.code,{children:"select"})," query above will return two ",(0,s.jsx)(n.em,{children:"additional"})," rows:"]}),"\n",(0,s.jsxs)(n.table,{children:[(0,s.jsx)(n.thead,{children:(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.th,{children:"user_name"}),(0,s.jsx)(n.th,{children:"file_name"})]})}),(0,s.jsxs)(n.tbody,{children:[(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"emily"}),(0,s.jsx)(n.td,{children:"financials"})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"emily"}),(0,s.jsx)(n.td,{children:"f3"})]})]})]}),"\n",(0,s.jsx)(n.h2,{id:"running-at-full-speed",children:"Running at full speed"}),"\n",(0,s.jsx)(n.p,{children:"The SQL code below demonstrates the same program as before, but now configured\nwith a data generator that builds a random object graph with 1,000 users, 100 groups,\n100 top-level folders, 1,000 sub-folders, and 100,000 files randomly distributed\nacross the sub-folders. The generator runs continuously, dynamically updating the\nrandom set of 100,000 files. Additionally, it continuously modifies user group\nmemberships."}),"\n",(0,s.jsxs)(r,{children:[(0,s.jsx)("summary",{children:" Expand to see full SQL code "}),(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-sql",children:'CREATE TABLE users (\n    id BIGINT NOT NULL PRIMARY KEY,\n    name STRING,\n    is_banned BOOL\n) WITH (\n  \'materialized\' = \'true\',\n  -- Generate 1000 random users\n  \'connectors\' = \'[{\n    "transport": {\n      "name": "datagen",\n      "config": {\n        "plan": [{\n            "limit": 1000,\n            "fields": {\n                "name": { "strategy": "name" }\n            }\n        }]\n      }\n    }\n  }]\'\n);\n\nCREATE TABLE groups (\n    id BIGINT NOT NULL PRIMARY KEY,\n    name STRING\n) WITH (\n  \'materialized\' = \'true\',\n  -- Generate 100 random groups\n  \'connectors\' = \'[{\n    "transport": {\n      "name": "datagen",\n      "config": {\n        "plan": [{\n            "limit": 100,\n            "fields": {\n                "name": { "strategy": "word" }\n            }\n        }]\n      }\n    }\n  }]\'\n);\n\nCREATE TABLE files (\n    id BIGINT NOT NULL PRIMARY KEY,\n    name STRING,\n    -- Parent folder id when not NULL\n    parent_id BIGINT\n) WITH (\n  \'materialized\' = \'true\',\n  -- Generate a file hierarchy with 100 top-level folders, 1,000 sub-folders, and 100,000 files\n  -- randomly distributed across sub-folders. The generator will continue running indefinitely\n  -- randomly updating the 100,000 files.\n  \'connectors\' = \'[{\n    "transport": {\n      "name": "datagen",\n      "config": {\n        "plan": [{\n            "limit": 100,\n            "fields": {\n                "id": { "range": [0, 100] },\n                "name": { "strategy": "word" },\n                "parent_id": { "null_percentage": 100 }\n            }\n        },\n        {\n            "limit": 1000,\n            "fields": {\n                "id": { "range": [100, 1100] },\n                "name": { "strategy": "word" },\n                "parent_id": { "range": [0,100] }\n            }\n        },\n        {\n            "fields": {\n                "id": { "range": [1100, 101100] },\n                "name": { "strategy": "word" },\n                "parent_id": { "range": [100,1100], "strategy": "uniform" }\n            }\n        }\n        ]\n      }\n    }\n  }]\'\n);\n\n-- Member relationship models user membership in groups.\nCREATE TABLE members (\n    id BIGINT NOT NULL PRIMARY KEY,\n    user_id  BIGINT NOT NULL,\n    group_id BIGINT NOT NULL\n) WITH (\n  \'materialized\' = \'true\',\n  -- Assign each use to 3 randomly selected groups. The generator will continue running indefinitely\n  -- randomly re-assigning users to groups.\n  \'connectors\' = \'[{\n    "transport": {\n      "name": "datagen",\n      "config": {\n        "plan": [{\n            "rate": 1000,\n            "fields": {\n                "id": { "range": [0,3000] },\n                "user_id": {"range": [0, 1000], "strategy": "zipf"},\n                "group_id": {"range": [0, 100], "strategy": "zipf"}\n            }\n        }]\n      }\n    }\n  }]\'\n);\n\n-- Editor relationship between a group and a file that gives the group the permission\n-- to read or write the file.\nCREATE TABLE group_file_editor (\n    group_id BIGINT NOT NULL,\n    file_id BIGINT NOT NULL\n) WITH (\n  \'materialized\' = \'true\',\n  -- Randomly assign one group as an editor to each top-level folder.\n  \'connectors\' = \'[{\n    "transport": {\n      "name": "datagen",\n      "config": {\n        "plan": [{\n            "limit": 100,\n            "fields": {\n                "group_id": {"range": [0, 100], "strategy": "uniform"},\n                "file_id": {"range": [0, 100] }\n            }\n        }]\n      }\n    }\n  }]\'\n);\n\n-- Viewer relationship between a group and a file that gives the group the permission to read the file.\nCREATE TABLE group_file_viewer (\n    group_id BIGINT NOT NULL,\n    file_id BIGINT NOT NULL\n) WITH (\n  \'materialized\' = \'true\',\n  -- Give viewer permissions to 10 randomly selected subfolders to each user group.\n  \'connectors\' = \'[{\n    "transport": {\n      "name": "datagen",\n      "config": {\n        "plan": [{\n            "limit": 1000,\n            "fields": {\n                "group_id": {"range": [0, 100]},\n                "file_id": {"range": [100, 1100], "strategy": "uniform" }\n            }\n        }]\n      }\n    }\n  }]\'\n);\n\nDECLARE RECURSIVE VIEW group_can_write (\n    group_id BIGINT NOT NULL,\n    file_id BIGINT NOT NULL\n);\n\nCREATE MATERIALIZED VIEW group_can_write AS\n-- Rule 1: editor(group, file) -> group-can-write(group, file).\n(\n  SELECT group_id, file_id FROM group_file_editor\n)\nUNION ALL\n-- Rule 2: group-can-write(group, file1) and parent(file1, file2) -> group-can-write(group, file2).\n(\n  SELECT\n    group_can_write.group_id,\n    files.id AS file_id\n  FROM\n    group_can_write JOIN files ON group_can_write.file_id = files.parent_id\n);\n\nDECLARE RECURSIVE VIEW group_can_read (\n    group_id BIGINT NOT NULL,\n    file_id BIGINT NOT NULL\n);\n\nCREATE MATERIALIZED VIEW group_can_read AS\n-- Rule 3: viewer(group, file) -> group-can-read(group, file).\n(\n  SELECT group_id, file_id FROM group_file_viewer\n)\nUNION ALL\n-- Rule 4: group-can-write(group, file) -> group-can-read(group, file).\n(\n  SELECT group_id, file_id FROM group_can_write\n)\nUNION ALL\n-- Rule 5: group-can-read(group, file1) and parent(file1, file2) -> group-can-read(group, file2).\n(\n  SELECT\n    group_can_read.group_id,\n    files.id AS file_id\n FROM\n    group_can_read JOIN files ON group_can_read.file_id = files.parent_id\n);\n\n-- Rule 6: member(user, group) and group-can-write(group, file) and (not user.is_banned) -> user-can-write(user, file).\nCREATE MATERIALIZED VIEW user_can_write AS\nSELECT DISTINCT\n    members.user_id,\n    group_can_write.file_id\nFROM\n    members\n    JOIN group_can_write ON members.group_id = group_can_write.group_id\n    JOIN users ON users.id = members.user_id\nWHERE NOT users.is_banned;\n\n-- Rule 7: member(user, group) and group-can-read(group, file) and (not user.is_banned) -> user-can-read(user, file).\nCREATE MATERIALIZED VIEW user_can_read AS\nSELECT DISTINCT\n    members.user_id,\n    group_can_read.file_id\nFROM\n    members\n    JOIN group_can_read ON members.group_id = group_can_read.group_id\n    JOIN users ON users.id = members.user_id\nWHERE NOT users.is_banned;\n'})})]}),"\n",(0,s.jsx)(n.p,{children:"Running on a MacBook Pro with M3 Max CPU, this program achieves sustained throughput of 115K updates/s,\nmeaning that it processes 115K object graph changes/s and updates all derived relationships."})]})}function c(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(u,{...e})}):u(e)}},28453(e,n,r){r.d(n,{R:()=>d,x:()=>t});var i=r(96540);const s={},a=i.createContext(s);function d(e){const n=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function t(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:d(e.components),i.createElement(a.Provider,{value:n},e.children)}}}]);